/**
 * Calendar arithmetic for recurring issues: which `YYYY-MM-DD` dates are real,
 * which IANA zones exist, the local calendar day at an instant, and the latest
 * occurrence that has started by then.
 *
 * Pure functions only. Dates are compared as strings, which is correct for
 * zero-padded `YYYY-MM-DD`.
 */
import type { RecurrenceCadence } from "@/types/recurring-issue";

const CALENDAR_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * IANA names are letters, digits, `_`, `+`, `-` separated by `/`, and start with
 * a letter. This rejects UTC offsets such as `+05:00` or `-03`, which
 * `Intl.DateTimeFormat` would otherwise accept.
 */
const IANA_NAME = /^[A-Za-z][A-Za-z0-9_+-]*(\/[A-Za-z0-9_+-]+)*$/;

/** True for a `YYYY-MM-DD` string naming a real day, e.g. not `2026-02-30`. */
export function isCalendarDate(value: string): boolean {
  if (!CALENDAR_DATE.test(value)) return false;
  const [year, month, day] = parseParts(value);
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True when the runtime knows `zone` as an IANA time zone. */
export function isValidTimeZone(zone: string): boolean {
  if (!IANA_NAME.test(zone)) return false;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: zone });
    return true;
  } catch {
    return false;
  }
}

/** The calendar day (`YYYY-MM-DD`) that `instant` falls on in `timeZone`. */
export function localDateOn(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

  const part = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((candidate) => candidate.type === type)?.value ?? "";

  return `${part("year")}-${part("month")}-${part("day")}`;
}

/** ISO weekday of a calendar date: 1 = Monday … 7 = Sunday. */
export function isoWeekdayOf(date: string): number {
  const [year, month, day] = parseParts(date);
  const value = new Date(0);
  value.setUTCFullYear(year, month - 1, day);
  const sundayFirst = value.getUTCDay();
  return sundayFirst === 0 ? 7 : sundayFirst;
}

/**
 * The latest occurrence day on or before `today` (a local calendar date) that
 * is on or after `startsOn`, or `null` when none has started yet. An
 * occurrence day has started once its local midnight has passed, so `today`
 * itself counts.
 */
export function latestOccurrenceOn(
  rule: {
    readonly cadence: RecurrenceCadence;
    readonly weekday: number | null;
    readonly startsOn: string;
  },
  today: string,
): string | null {
  if (rule.cadence === "daily") {
    return today >= rule.startsOn ? today : null;
  }

  if (rule.weekday === null) return null;

  const daysBack = (isoWeekdayOf(today) - rule.weekday + 7) % 7;
  const candidate = addDays(today, -daysBack);
  return candidate >= rule.startsOn ? candidate : null;
}

/** Calendar arithmetic on a `YYYY-MM-DD` date, independent of any zone. */
export function addDays(date: string, days: number): string {
  const [year, month, day] = parseParts(date);
  const value = new Date(0);
  value.setUTCFullYear(year, month - 1, day + days);
  return [
    String(value.getUTCFullYear()).padStart(4, "0"),
    String(value.getUTCMonth() + 1).padStart(2, "0"),
    String(value.getUTCDate()).padStart(2, "0"),
  ].join("-");
}

function parseParts(date: string): [number, number, number] {
  const [year, month, day] = date.split("-").map(Number);
  return [year ?? 0, month ?? 0, day ?? 0];
}

