import { z } from "zod";
import { isCalendarDate, isValidTimeZone } from "@/lib/recurrence";
import { issuePrioritySchema } from "./issue";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";

/**
 * A recurring-issue rule as the user submits it. A weekly rule needs a
 * weekday and a daily rule must not carry one, so those pairings are checked
 * together after the individual fields parse.
 */
export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3, "give the recurring issue a title").max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z
      .string()
      .refine(isValidTimeZone, "must be an IANA time zone, e.g. Europe/Paris"),
    startsOn: z
      .string()
      .refine(isCalendarDate, "must be a real date in YYYY-MM-DD form"),
  })
  .superRefine((input, ctx) => {
    if (input.cadence === "weekly" && input.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "a weekly recurring issue needs a weekday",
      });
    }
    if (input.cadence === "daily" && input.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "a daily recurring issue cannot have a weekday",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<
  typeof createRecurringIssueSchema
>;

