/**
 * Recurring-issue rules: the standing definitions the job files issues from.
 *
 * Every read and write is org-scoped except `listActiveRecurringIssues`, which
 * the background job reads across tenants on purpose.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toRecurringIssue } from "./_mappers";
import type { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import type { z } from "zod";
import type { OrgId, UserId } from "@/types/common";
import type { RecurringIssue } from "@/types/recurring-issue";

type NewRecurringIssue = z.output<typeof createRecurringIssueSchema>;

export async function findRecurringIssue(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

/** Creation order: `rowid` breaks ties between rules created in the same millisecond. */
export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), asc(sql`rowid`))
    .all();
  return rows.map(toRecurringIssue);
}

/** Every rule the plan quota counts, paused ones included. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/**
 * Non-paused rules across every organization. Cross-tenant on purpose: the
 * job is a background sweep, not a request, and each rule carries its own org.
 */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt), asc(sql`rowid`))
    .all();
  return rows.map(toRecurringIssue);
}

export async function insertRecurringIssue(
  input: NewRecurringIssue,
  createdBy: UserId,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toRecurringIssue(row);
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
