import { wouldExceedLimit } from "@/config/plan-limits";
import { can } from "@/lib/permissions";
import { createLogger } from "@/lib/logger";
import { latestOccurrenceOn, localDateOn } from "@/lib/recurrence";
import { isArchived } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/**
 * One pass over every non-paused rule. A rule that throws is counted as failed
 * and left as it was, so the other rules still run. Missed occurrences are
 * never back-filled: each rule files at most one issue per pass, for the
 * latest occurrence that has started.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        if (await fileDueOccurrence(rule, now)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Returns true when an issue was filed for the rule on this pass. */
async function fileDueOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<boolean> {
  const occurrence = latestOccurrenceOn(rule, localDateOn(now, rule.timezone));
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) {
    throw new Error(`Project ${rule.projectId} was not found`);
  }
  if (isArchived(project)) return false;

  const actor = await creatorActor(rule);
  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return false;
  }

  // The same per-project ceiling the manual create action enforces. Archived
  // issues still occupy it, so they are counted here too.
  const org = await orgRepo.findOrgById(rule.orgId);
  if (org === null) throw new Error(`Organization ${rule.orgId} was not found`);
  const used = await issueRepo.countIssues(rule.orgId, rule.projectId, {
    includeArchived: true,
  });
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  await createIssue(actor, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId: await liveAssignee(rule),
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringIssueRepo.recordRecurringOccurrence(
    rule.orgId,
    rule.id,
    occurrence,
  );
  return true;
}

/** The creator as an actor, or `null` when they are no longer an active member. */
async function creatorActor(rule: RecurringIssue): Promise<Actor | null> {
  const member = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (member === null || member.status !== "active") return null;
  return { userId: rule.createdBy, orgId: rule.orgId, role: member.role };
}

/** The rule's assignee if they are still an active member, otherwise unassigned. */
async function liveAssignee(rule: RecurringIssue) {
  if (rule.assigneeId === null) return null;
  const member = await memberRepo.findMember(rule.orgId, rule.assigneeId);
  return member?.status === "active" ? rule.assigneeId : null;
}

