import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { getDb, projects } from "@/server/db";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import * as memberRepo from "@/server/repositories/member-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import * as service from "@/server/services/recurring-issue-service";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { latestOccurrenceOn, localDateOn, isValidTimeZone, isCalendarDate } from "@/lib/recurrence";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId, ProjectId, UserId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});
afterAll(() => cleanup());

const base = {
  title: "Daily triage",
  priority: "high" as const,
  assigneeId: null,
  cadence: "daily" as const,
  weekday: null,
  timezone: "UTC",
  startsOn: "2026-03-01",
};

describe("schema", () => {
  it("accepts a valid daily rule and applies defaults", () => {
    const parsed = createRecurringIssueSchema.parse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      projectId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      title: "Chore",
      cadence: "daily",
      timezone: "Europe/Paris",
      startsOn: "2026-03-01",
    });
    expect(parsed.priority).toBe("none");
    expect(parsed.assigneeId).toBeNull();
    expect(parsed.weekday).toBeNull();
  });

  it("enforces weekday/cadence pairing, zone, date and title length", () => {
    const org = "01HZZZAAAAAAAAAAAAAAAAAAAA";
    const cases: Array<[string, Record<string, unknown>]> = [
      ["weekly w/o weekday", { cadence: "weekly", weekday: null }],
      ["daily with weekday", { cadence: "daily", weekday: 1 }],
      ["bad zone", { timezone: "Mars/Olympus" }],
      ["offset zone", { timezone: "+05:00" }],
      ["feb 30", { startsOn: "2026-02-30" }],
      ["short title", { title: "ab" }],
      ["weekday 8", { cadence: "weekly", weekday: 8 }],
    ];
    for (const [label, override] of cases) {
      const result = createRecurringIssueSchema.safeParse({ ...base, orgId: org, projectId: org, ...override });
      expect(result.success, label).toBe(false);
    }
    const ok = createRecurringIssueSchema.safeParse({ ...base, orgId: org, projectId: org, cadence: "weekly", weekday: 4 });
    expect(ok.success).toBe(true);
  });

  it("validates calendar dates and zones directly", () => {
    expect(isCalendarDate("2028-02-29")).toBe(true);
    expect(isCalendarDate("2026-02-29")).toBe(false);
    expect(isValidTimeZone("America/New_York")).toBe(true);
    expect(isValidTimeZone("-03")).toBe(false);
  });
});

describe("occurrences", () => {
  it("daily uses local calendar day in the zone", () => {
    // 16:00 UTC on Mar 4 is 01:00 on Mar 5 in Tokyo.
    const now = new Date("2026-03-04T16:00:00Z");
    expect(localDateOn(now, "Asia/Tokyo")).toBe("2026-03-05");
    expect(localDateOn(now, "UTC")).toBe("2026-03-04");
    expect(latestOccurrenceOn({ cadence: "daily", weekday: null, startsOn: "2026-03-01" }, "2026-03-05")).toBe("2026-03-05");
    expect(latestOccurrenceOn({ cadence: "daily", weekday: null, startsOn: "2026-03-06" }, "2026-03-05")).toBeNull();
  });

  it("weekly picks the latest matching ISO weekday on or after startsOn", () => {
    // 2026-03-05 is a Thursday (ISO 4). Monday rule -> Mar 2.
    expect(latestOccurrenceOn({ cadence: "weekly", weekday: 1, startsOn: "2026-02-01" }, "2026-03-05")).toBe("2026-03-02");
    expect(latestOccurrenceOn({ cadence: "weekly", weekday: 4, startsOn: "2026-03-01" }, "2026-03-05")).toBe("2026-03-05");
    expect(latestOccurrenceOn({ cadence: "weekly", weekday: 7, startsOn: "2026-03-04" }, "2026-03-05")).toBeNull();
  });

  it("handles DST transitions for the local day", () => {
    // New York springs forward 2026-03-08 at 07:00 UTC.
    expect(localDateOn(new Date("2026-03-08T06:30:00Z"), "America/New_York")).toBe("2026-03-08");
    expect(localDateOn(new Date("2026-03-08T04:30:00Z"), "America/New_York")).toBe("2026-03-07");
  });
});

describe("service + job", () => {
  it("creates, enforces tenant/permission/archive/assignee/quota, and the job files once per occurrence", async () => {
    const tenant = await createTenant("recur-a", "growth");
    const orgId = tenant.org.id as OrgId;
    await usageRepo.recomputeUsage(orgId);
    const creator = tenant.actors.member;

    // Tenant scope
    await expect(
      service.createRecurringIssue(creator, { ...base, orgId: "01HZZZBBBBBBBBBBBBBBBBBBBB", projectId: tenant.project.id }),
    ).rejects.toMatchObject({ code: "tenant_scope_violation" });

    // Viewer cannot create
    await expect(
      service.createRecurringIssue(tenant.actors.viewer, { ...base, orgId, projectId: tenant.project.id }),
    ).rejects.toMatchObject({ code: "forbidden" });

    // Invalid schema -> ZodError
    await expect(
      service.createRecurringIssue(creator, { ...base, orgId, projectId: tenant.project.id, cadence: "weekly" }),
    ).rejects.toMatchObject({ name: "ZodError" });

    // Non-member assignee
    await expect(
      service.createRecurringIssue(creator, { ...base, orgId, projectId: tenant.project.id, assigneeId: "01HZZZBBBBBBBBBBBBBBBBBBB2" as UserId }),
    ).rejects.toThrow();

    // Valid create
    const rule = await service.createRecurringIssue(creator, {
      ...base,
      orgId,
      projectId: tenant.project.id,
      assigneeId: tenant.userIds.admin,
      timezone: "Asia/Tokyo",
    });
    expect(rule.lastOccurrenceOn).toBeNull();
    expect(rule.paused).toBe(false);
    expect(rule.createdBy).toBe(creator.userId);

    const listed = await service.listRecurringIssues(tenant.actors.viewer, orgId);
    expect(listed.map((row) => row.id)).toEqual([rule.id]);

    // Job: 2026-03-04T16:00Z is Mar 5 in Tokyo -> files "Daily triage (2026-03-05)".
    const now = new Date("2026-03-04T16:00:00Z");
    const first = await runRecurringIssueJob(now);
    expect(first.processed).toBe(1);
    expect(first.failed).toBe(0);
    const again = await runRecurringIssueJob(now);
    expect(again.processed).toBe(0);

    const issues = await issueRepo.listIssues({ orgId, projectId: tenant.project.id, limit: 100, cursor: null } as never);
    const filed = issues.items.filter((issue) => issue.title.startsWith("Daily triage"));
    expect(filed.length).toBe(1);
    expect(filed[0]?.title).toBe("Daily triage (2026-03-05)");
    expect(filed[0]?.status).toBe("backlog");
    expect(filed[0]?.priority).toBe("high");
    expect(filed[0]?.assigneeId).toBe(tenant.userIds.admin);
    expect(filed[0]?.authorId).toBe(creator.userId);

    // Next day: a new occurrence is filed; no back-fill for skipped days.
    const later = await runRecurringIssueJob(new Date("2026-03-10T12:00:00Z"));
    expect(later.processed).toBe(1);
    const stored = await recurringRepo.findRecurringIssue(orgId, rule.id);
    expect(stored?.lastOccurrenceOn).toBe("2026-03-11");

    // Pause, then job files nothing while paused.
    await service.setRecurringIssuePaused(tenant.actors.owner, { orgId, recurringIssueId: rule.id, paused: true });
    const paused = await runRecurringIssueJob(new Date("2026-03-20T12:00:00Z"));
    expect(paused.processed).toBe(0);

    // Not-found for unknown id
    await expect(
      service.setRecurringIssuePaused(creator, { orgId, recurringIssueId: "nope", paused: false }),
    ).rejects.toMatchObject({ code: "not_found" });
  });

  it("archived project is skipped and left unchanged; creator leaving pauses the rule", async () => {
    const tenant = await createTenant("recur-b", "growth");
    const orgId = tenant.org.id as OrgId;
    await usageRepo.recomputeUsage(orgId);
    const creator = tenant.actors.member;

    const rule = await service.createRecurringIssue(creator, { ...base, orgId, projectId: tenant.project.id, title: "Weekly plan", cadence: "weekly", weekday: 1 });

    // Archive the project directly.
    getDb().update(projects).set({ archivedAt: toIsoTimestamp(new Date()) }).where(eq(projects.id, tenant.project.id as ProjectId)).run();
    const skipped = await runRecurringIssueJob(new Date("2026-03-09T12:00:00Z"));
    expect(skipped.processed).toBe(0);
    expect((await recurringRepo.findRecurringIssue(orgId, rule.id))?.paused).toBe(false);
    expect((await recurringRepo.findRecurringIssue(orgId, rule.id))?.lastOccurrenceOn).toBeNull();

    // Restore, then creator is removed -> paused, nothing filed.
    getDb().update(projects).set({ archivedAt: null }).where(eq(projects.id, tenant.project.id as ProjectId)).run();
    const member = await memberRepo.findMember(orgId, creator.userId);
    await memberRepo.archiveMember(orgId, member!.id);
    const result = await runRecurringIssueJob(new Date("2026-03-09T12:00:00Z"));
    expect(result.processed).toBe(0);
    expect((await recurringRepo.findRecurringIssue(orgId, rule.id))?.paused).toBe(true);
  });
});

