    await usageRepo.recomputeUsage(orgId);
    const creator = tenant.actors.member;

    const rule = await service.createRecurringIssue(creator, { ...base, orgId, projectId: tenant.project.id, title: "Weekly plan", cadence: "weekly", weekday: 1 });

    // Archive the project directly.
    getDb().update(projects).set({ archivedAt: toIsoTimestamp(new Date()) }).where(eq(projects.id, tenant.project.id as ProjectId)).run();
    const skipped = await runRecurringIssueJob(new Date("2026-03-09T12:00:00Z"));
    expect(skipped.processed).toBe(0);
    expect((await recurringRepo.findRecurringIssue(orgId, rule.id))?.paused).toBe(false);
    expect((await recurringRepo.findRecurringIssue(orgId, rule.id))?.lastOccurrenceOn).toBeNull();

    // Restore, then creator is removed -> paused, nothing filed.
    getDb().update(projects).set({ archivedAt: null }).where(eq(projects.id, tenant.project.id as ProjectId)).run();
    const member = await memberRepo.findMember(orgId, creator.userId);
    await memberRepo.archiveMember(orgId, member!.id);
    const result = await runRecurringIssueJob(new Date("2026-03-09T12:00:00Z"));
    expect(result.processed).toBe(0);
    expect((await recurringRepo.findRecurringIssue(orgId, rule.id))?.paused).toBe(true);
  });
});
